function e(e,{decimals:t=1,hours:n=!1}={}){let r=10**t,i=Number.isFinite(e)&&e>0?Math.round(e*r):0,a=Math.floor(i/r),o=i%r,s=String(a%60).padStart(2,`0`),c=t>0?`.${String(o).padStart(t,`0`)}`:``,l=Math.floor(a/60);if(n&&l>=60){let e=String(l%60).padStart(2,`0`);return`${Math.floor(l/60)}:${e}:${s}${c}`}return`${l}:${s}${c}`}function t(e){let t=Number.isFinite(e)&&e>0?Math.round(e):0;return{minutes:Math.floor(t/60),seconds:t%60}}export{t as n,e as t};